import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.List;

public class Settings {
    static int readPort(Path file) throws IOException {
        List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);   // explicit charset.
        for (String line : lines) {
            if (line.startsWith("port=")) {
                int port = Integer.parseInt(line.substring(5).trim());
                if (port < 1 || port > 65535) throw new IllegalStateException("bad port " + port);
                return port;
            }
        }
        throw new IllegalStateException("no port line");         // malformed content.
    }

    public static void main(String[] args) throws IOException {
        Path dir = Files.createTempDirectory("app");
        Path file = dir.resolve("settings.txt");
        Path tmp = dir.resolve("settings.tmp");
        Files.writeString(tmp, "port=8080\n", StandardCharsets.UTF_8);
        Files.move(tmp, file, StandardCopyOption.REPLACE_EXISTING);   // no half-written file.
        System.out.println(readPort(file));                       // 8080
        try { readPort(dir.resolve("nope.txt")); }
        catch (NoSuchFileException e) { System.out.println("missing"); }   // missing
    }
}
